#pragma once
#include "stem_separator.hpp"
namespace vamp {
class ProjectImporter{
    std::thread worker;std::mutex mutex;std::wstring detail;Json response;
public:
    std::atomic<bool>busy{false},done{false},cancel{false};std::atomic<float>progress{0};fs::path directory;
    ~ProjectImporter(){cancel=true;if(worker.joinable())worker.join();}
    std::wstring status(){std::lock_guard<std::mutex>lock(mutex);return detail;}
    Json result(){if(worker.joinable())worker.join();done=false;return response;}
    void start(const fs::path&python,const fs::path&script,const fs::path&encoder,const fs::path&source,const fs::path&output,HWND host){if(busy)throw std::runtime_error("A project import is already running");if(!fs::is_regular_file(python)||!fs::is_regular_file(script))throw std::runtime_error("Project importer is missing. Reinstall the current VampDAW alpha.");if(worker.joinable())worker.join();directory=output;cancel=false;done=false;busy=true;progress=0;response=Json::object();{std::lock_guard<std::mutex>lock(mutex);detail=source.filename().wstring();}
        try{worker=std::thread([=]{HANDLE process=nullptr,job=nullptr;try{fs::create_directories(output);job=CreateJobObjectW(nullptr,nullptr);JOBOBJECT_EXTENDED_LIMIT_INFORMATION limits{};limits.BasicLimitInformation.LimitFlags=JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE;if(!job||!SetInformationJobObject(job,JobObjectExtendedLimitInformation,&limits,sizeof limits))throw std::runtime_error("Cannot isolate project importer");std::wstring command=processArgument(python.wstring())+L" -I -B "+processArgument(script.wstring())+L" --source "+processArgument(source.wstring())+L" --output "+processArgument(output.wstring())+L" --encoder "+processArgument(encoder.wstring());STARTUPINFOW startup{sizeof startup};PROCESS_INFORMATION info{};if(!CreateProcessW(python.c_str(),command.data(),nullptr,nullptr,FALSE,CREATE_NO_WINDOW|CREATE_SUSPENDED|BELOW_NORMAL_PRIORITY_CLASS,nullptr,output.c_str(),&startup,&info))throw std::runtime_error("Cannot launch project importer");process=info.hProcess;if(!AssignProcessToJobObject(job,process)||ResumeThread(info.hThread)==(DWORD)-1){TerminateProcess(process,1);CloseHandle(info.hThread);throw std::runtime_error("Cannot start isolated project importer");}CloseHandle(info.hThread);auto started=GetTickCount64();DWORD wait=WAIT_TIMEOUT;while((wait=WaitForSingleObject(process,100))==WAIT_TIMEOUT){if(cancel||GetTickCount64()-started>30*60*1000){TerminateJobObject(job,1);throw std::runtime_error(cancel?"Project import cancelled":"Project import timed out");}try{std::ifstream f(output/L"status.json");Json j;if(f){f>>j;if(j.is_object()){progress=(float)clamp(j.value("progress",0.),0,1);std::lock_guard<std::mutex>lock(mutex);detail=wide(j.value("stage","Importing project"));}}}catch(...){} }
                DWORD code=1;if(wait!=WAIT_OBJECT_0||!GetExitCodeProcess(process,&code))throw std::runtime_error("Cannot read importer exit status");auto report=output/L"report.json";if(!fs::is_regular_file(report)||fs::file_size(report)>8*1024*1024)throw std::runtime_error("Project importer returned no valid report");std::ifstream f(report);f>>response;if(code||!response.is_object()||!response.value("passed",false))throw std::runtime_error(response.is_object()?response.value("error","Project import failed"):"Project import failed");progress=1;
            }catch(const std::exception&e){response={{"passed",false},{"cancelled",cancel.load()},{"error",e.what()}};}catch(...){response={{"passed",false},{"error","Unexpected project import error"}};}if(job)CloseHandle(job);if(process)CloseHandle(process);busy=false;done=true;PostMessageW(host,WM_APP+34,0,0);});}catch(...){busy=false;throw;}}
};
}
